-- 43. Tommy Franks (backfill)
INSERT OR IGNORE INTO content_section
  (id, entity_id, section_type, heading, body_markdown, claim_ids, source_ids,
   reading_level, language, author_type, generator_version, editorial_status, version,
   display_order, last_verified_at, last_verified_by, word_count)
VALUES
  ('cs_tommy-franks_career', 'ent_tommy-franks', 'career', 'Career', 'Tommy Ray Franks (born 17 June 1945) is a retired United States Army general. His last army post was as the Commander of the United States Central Command, overseeing United States military operations in a 25-country region, including the Middle East. Franks succeeded General Anthony Zinni to this position on 6 July 2000 and served until his retirement on 7 July 2003.
Franks was the United States general leading the attack on the Taliban in Afghanistan in response to the September 11 attacks on the United States in 2001. He also oversaw the 2003 invasion of Iraq and the overthrow of Saddam Hussein.',
   '["clm_wiki_tommy-franks_career"]', '["src_wikidata"]',
   'general', 'en', 'assisted', 'kp-025-migration-0025', 'auto_approved', 1,
   20, unixepoch(), 'wikipedia', 103);

