-- 102. Septima Poinsette Clark (backfill)
INSERT OR IGNORE INTO content_section
  (id, entity_id, section_type, heading, body_markdown, claim_ids, source_ids,
   reading_level, language, author_type, generator_version, editorial_status, version,
   display_order, last_verified_at, last_verified_by, word_count)
VALUES
  ('cs_septima-clark_career', 'ent_septima-clark', 'career', 'Career', 'Septima Poinsette Clark (May 3, 1898 – December 15, 1987) was an African American educator and civil rights activist. Clark developed the literacy and citizenship workshops that played an important role in the drive for voting rights and civil rights for African Americans in the Civil Rights Movement. Septima Clark''s work was commonly under-appreciated by Southern male activists. She became known as the "Queen Mother" or "Grandmother" of the Civil Rights Movement in the United States. Martin Luther King Jr. commonly referred to Clark as "The Mother of the Movement".  Clark''s argument for her position in the Civil Rights Movement was one that claimed "knowledge could empower marginalized groups in ways that formal legal equality couldn''t."',
   '["clm_wiki_septima-clark_career"]', '["src_wikidata"]',
   'general', 'en', 'assisted', 'kp-025-migration-0025', 'auto_approved', 1,
   20, unixepoch(), 'wikipedia', 116);

